SELECT cliente_id, nombre
FROM clientes
WHERE municipio IS NULL;

SELECT producto_id, nombre
FROM productos
WHERE nombre LIKE '%(kg)%';

SELECT DISTINCT estado
FROM pedidos
ORDER BY estado;

SELECT pr.producto_id, pr.nombre
FROM productos pr
WHERE NOT EXISTS (
    SELECT 1 FROM detalle_pedido d WHERE d.producto_id = pr.producto_id
);

SELECT e.nombre, e.area, e.salario
FROM empleados e
WHERE e.salario > (
    SELECT AVG(x.salario) FROM empleados x WHERE x.area = e.area
)
ORDER BY e.area, e.salario DESC;

SELECT MAX(salario) AS segundo_mas_alto
FROM empleados
WHERE salario < (SELECT MAX(salario) FROM empleados);
